const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const N = input[idx++];
const M = input[idx++];

const graph = Array.from({ length: N }, () => []);

for (let i = 0; i < M; i++) {
  const a = input[idx++] - 1;
  const b = input[idx++] - 1;
  const cost = input[idx++];

  graph[a].push([b, cost]);
  graph[b].push([a, cost]);
}

const dist = Array(N).fill(Infinity);
const visited = Array(N).fill(false);
dist[0] = 0;

for (let i = 0; i < N; i++) {
  let u = -1;

  for (let j = 0; j < N; j++) {
    if (!visited[j] && (u === -1 || dist[j] < dist[u])) {
      u = j;
    }
  }

  visited[u] = true;

  for (const [v, cost] of graph[u]) {
    if (dist[u] + cost < dist[v]) {
      dist[v] = dist[u] + cost;
    }
  }
}

console.log(dist[N - 1].toString());
